'use client';

import React, { useEffect, useRef, useCallback } from 'react';
import type { Terminal as XTermTerminal } from '@xterm/xterm';
import type { FitAddon as XTermFitAddon } from '@xterm/addon-fit';
import '@xterm/xterm/css/xterm.css';

interface InnerAgentTerminalProps {
  dveId: string;
  sessionId: string;
  toolName: string;
  isVisible: boolean;
}

// Resolve the WebSocket base URL from the current page origin.
function wsBaseUrl(): string {
  if (typeof window === 'undefined') return 'ws://localhost';
  const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  return `${proto}//${window.location.host}`;
}

export function InnerAgentTerminal({ dveId, sessionId, toolName, isVisible }: InnerAgentTerminalProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const termRef = useRef<XTermTerminal | null>(null);
  const fitRef = useRef<XTermFitAddon | null>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const mountedRef = useRef(false);

  const sendInput = useCallback((data: string) => {
    const ws = wsRef.current;
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: 'input', data }));
    }
  }, []);

  const sendResize = useCallback((cols: number, rows: number) => {
    const ws = wsRef.current;
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: 'resize', cols, rows }));
    }
  }, []);

  useEffect(() => {
    if (!containerRef.current || mountedRef.current) return;
    mountedRef.current = true;

    let term: XTermTerminal;
    let fitAddon: XTermFitAddon;

    const init = async () => {
      const { Terminal } = await import('@xterm/xterm');
      const { FitAddon } = await import('@xterm/addon-fit');
      const { WebLinksAddon } = await import('@xterm/addon-web-links');

      term = new Terminal({
        cursorBlink: true,
        fontSize: 12,
        fontFamily: 'Menlo, Monaco, "Courier New", monospace',
        theme: {
          background: '#03050a',
          foreground: '#d4d4d4',
          cursor: '#a855f7',
          selectionBackground: 'rgba(168,85,247,0.25)',
        },
        // Raw mode — inner agents handle echo themselves
        convertEol: false,
      });

      fitAddon = new FitAddon();
      term.loadAddon(fitAddon);
      term.loadAddon(new WebLinksAddon());

      if (containerRef.current) {
        term.open(containerRef.current);
        fitAddon.fit();
      }

      termRef.current = term;
      fitRef.current = fitAddon;

      term.writeln(`\x1b[35m[KNIRV]\x1b[0m Connecting to ${toolName} session ${sessionId.slice(0, 8)}…`);

      // Open WebSocket to /ws/{dveId}/inner/stream/{sessionId}
      const ws = new WebSocket(`${wsBaseUrl()}/ws/${dveId}/inner/stream/${sessionId}`);
      wsRef.current = ws;

      ws.onopen = () => {
        term.writeln(`\x1b[32m[CONNECTED]\x1b[0m ${toolName} PTY stream active`);
        const { cols, rows } = term;
        sendResize(cols, rows);
      };

      ws.onmessage = (ev) => {
        try {
          const msg = JSON.parse(ev.data) as { type: string; data?: string };
          if (msg.type === 'data' && msg.data) {
            term.write(msg.data);
          } else if (msg.type === 'stream_end') {
            term.writeln('\r\n\x1b[33m[SESSION ENDED]\x1b[0m');
          } else if (msg.type === 'error') {
            term.writeln(`\r\n\x1b[31m[ERROR]\x1b[0m ${msg.data}`);
          }
        } catch {
          // raw bytes fallback
          term.write(ev.data);
        }
      };

      ws.onclose = () => {
        term.writeln('\r\n\x1b[33m[DISCONNECTED]\x1b[0m WebSocket closed.');
      };

      ws.onerror = () => {
        term.writeln('\r\n\x1b[31m[ERROR]\x1b[0m WebSocket error — check DVE agent status.');
      };

      // Send keystrokes to PTY
      term.onData(sendInput);

      // Resize on terminal dimension change
      term.onResize(({ cols, rows }) => sendResize(cols, rows));
    };

    init();

    return () => {
      wsRef.current?.close();
      termRef.current?.dispose();
      mountedRef.current = false;
    };
  }, [dveId, sessionId, toolName, sendInput, sendResize]);

  // Re-fit when tab becomes visible
  useEffect(() => {
    if (isVisible && fitRef.current) {
      setTimeout(() => fitRef.current?.fit(), 50);
    }
  }, [isVisible]);

  return (
    <div
      ref={containerRef}
      className="w-full h-full"
      style={{ display: isVisible ? 'block' : 'none' }}
    />
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { X, Download, Play, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { type InnerAgentTool, useInnerAgent } from '@/hooks/use-inner-agent';

interface ToolPickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  dveId: string | undefined;
  onSpawned: (sessionId: string, toolName: string) => void;
}

const TOOL_DESCRIPTIONS: Record<string, string> = {
  claude: 'Anthropic Claude Code — AI coding assistant with full repo context',
  aider: 'Aider — pair programming with LLMs in your terminal',
  codex: 'OpenAI Codex CLI — AI agent for your terminal',
  'gh-copilot': 'GitHub Copilot CLI — AI coding assistant via gh extension',
};

export function ToolPickerModal({ isOpen, onClose, dveId, onSpawned }: ToolPickerModalProps) {
  const { tools, loading, error, listTools, installTool, spawnSession } = useInnerAgent(dveId);
  const [actionState, setActionState] = useState<Record<string, 'idle' | 'installing' | 'spawning' | 'done' | 'error'>>({});

  useEffect(() => {
    if (isOpen && dveId) {
      listTools();
    }
  }, [isOpen, dveId]);

  const handleInstall = async (tool: InnerAgentTool) => {
    setActionState(s => ({ ...s, [tool.name]: 'installing' }));
    const ok = await installTool(tool.name);
    setActionState(s => ({ ...s, [tool.name]: ok ? 'done' : 'error' }));
    if (ok) setTimeout(() => setActionState(s => ({ ...s, [tool.name]: 'idle' })), 1500);
  };

  const handleSpawn = async (tool: InnerAgentTool) => {
    setActionState(s => ({ ...s, [tool.name]: 'spawning' }));
    const sessionId = await spawnSession(tool.name);
    if (sessionId) {
      setActionState(s => ({ ...s, [tool.name]: 'done' }));
      onSpawned(sessionId, tool.name);
      onClose();
    } else {
      setActionState(s => ({ ...s, [tool.name]: 'error' }));
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60" onClick={onClose}>
      <div
        className="w-full max-w-md bg-[#0d1117] border border-purple-900/40 rounded-xl shadow-2xl"
        onClick={e => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-slate-800">
          <div>
            <h2 className="text-sm font-bold text-slate-100">Spawn Inner Agent</h2>
            <p className="text-[11px] text-slate-500 mt-0.5">Select a tool to run inside the DVE workspace</p>
          </div>
          <button onClick={onClose} className="text-slate-500 hover:text-slate-300 transition-colors">
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Body */}
        <div className="p-4 space-y-2">
          {loading && tools.length === 0 && (
            <div className="flex items-center justify-center py-8 text-slate-500">
              <Loader2 className="w-5 h-5 animate-spin mr-2" />
              <span className="text-sm">Loading tools...</span>
            </div>
          )}
          {error && (
            <div className="flex items-center gap-2 px-3 py-2 bg-red-900/20 border border-red-800/40 rounded-lg text-xs text-red-400">
              <AlertCircle className="w-4 h-4 shrink-0" />
              {error}
            </div>
          )}
          {tools.map(tool => {
            const state = actionState[tool.name] ?? 'idle';
            const isActing = state === 'installing' || state === 'spawning';
            return (
              <div
                key={tool.name}
                className="flex items-center justify-between px-4 py-3 rounded-lg bg-slate-900/50 border border-slate-800 hover:border-purple-800/50 transition-colors"
              >
                <div className="flex-1 min-w-0 mr-3">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-mono font-semibold text-purple-300">{tool.name}</span>
                    {tool.is_installed && (
                      <span className="text-[10px] bg-green-900/30 text-green-400 border border-green-800/40 px-1.5 py-0.5 rounded">
                        installed
                      </span>
                    )}
                  </div>
                  <p className="text-[11px] text-slate-500 mt-0.5 truncate">
                    {TOOL_DESCRIPTIONS[tool.name] ?? tool.binary}
                  </p>
                </div>

                <div className="flex items-center gap-2 shrink-0">
                  {state === 'done' && <CheckCircle2 className="w-4 h-4 text-green-400" />}
                  {state === 'error' && <AlertCircle className="w-4 h-4 text-red-400" />}

                  {!tool.is_installed ? (
                    <Button
                      size="sm"
                      variant="outline"
                      disabled={isActing}
                      onClick={() => handleInstall(tool)}
                      className="h-7 px-3 text-[11px] border-amber-800/40 text-amber-400 hover:bg-amber-900/20"
                    >
                      {state === 'installing' ? (
                        <Loader2 className="w-3 h-3 animate-spin mr-1" />
                      ) : (
                        <Download className="w-3 h-3 mr-1" />
                      )}
                      Install
                    </Button>
                  ) : (
                    <Button
                      size="sm"
                      disabled={isActing}
                      onClick={() => handleSpawn(tool)}
                      className="h-7 px-3 text-[11px] bg-purple-700 hover:bg-purple-600 text-white"
                    >
                      {state === 'spawning' ? (
                        <Loader2 className="w-3 h-3 animate-spin mr-1" />
                      ) : (
                        <Play className="w-3 h-3 mr-1" />
                      )}
                      Launch
                    </Button>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="px-5 py-3 border-t border-slate-800">
          <p className="text-[10px] text-slate-600">
            Inner agents run inside the DVE enclave workspace and are monitored by the KNIRVAGENT supervisor.
          </p>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { API_BASE_URL, getAuthHeaders } from '@/lib/api';

export interface InnerAgentTool {
  name: string;
  binary: string;
  is_installed: boolean;
}

export interface InnerAgentSession {
  id: string;
  tool_name: string;
  status: 'running' | 'exited';
  started_at: string;
}

export function useInnerAgent(dveId: string | undefined) {
  const [tools, setTools] = useState<InnerAgentTool[]>([]);
  const [sessions, setSessions] = useState<InnerAgentSession[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const listTools = useCallback(async () => {
    if (!dveId) return;
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/tools`, {
        headers: getAuthHeaders(),
      });
      if (resp.ok) {
        const data = await resp.json();
        setTools(Array.isArray(data) ? data : data.tools ?? []);
      }
    } catch (err) {
      setError(String(err));
    }
  }, [dveId]);

  const listSessions = useCallback(async () => {
    if (!dveId) return;
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/sessions`, {
        headers: getAuthHeaders(),
      });
      if (resp.ok) {
        const data = await resp.json();
        setSessions(Array.isArray(data) ? data : data.sessions ?? []);
      }
    } catch (err) {
      setError(String(err));
    }
  }, [dveId]);

  const installTool = useCallback(async (toolName: string): Promise<boolean> => {
    if (!dveId) return false;
    setLoading(true);
    setError(null);
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/install`, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify({ tool: toolName }),
      });
      if (!resp.ok) {
        const body = await resp.text();
        setError(`Install failed: ${body}`);
        return false;
      }
      await listTools();
      return true;
    } catch (err) {
      setError(String(err));
      return false;
    } finally {
      setLoading(false);
    }
  }, [dveId, listTools]);

  const spawnSession = useCallback(async (toolName: string): Promise<string | null> => {
    if (!dveId) return null;
    setLoading(true);
    setError(null);
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/spawn`, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify({ tool: toolName }),
      });
      if (!resp.ok) {
        const body = await resp.text();
        setError(`Spawn failed: ${body}`);
        return null;
      }
      const data = await resp.json();
      const sessionId: string = data.id ?? data.session_id;
      if (sessionId) {
        setSessions(prev => [...prev, {
          id: sessionId,
          tool_name: toolName,
          status: 'running',
          started_at: new Date().toISOString(),
        }]);
      }
      return sessionId ?? null;
    } catch (err) {
      setError(String(err));
      return null;
    } finally {
      setLoading(false);
    }
  }, [dveId]);

  const terminateSession = useCallback(async (sessionId: string) => {
    if (!dveId) return;
    try {
      await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/sessions/${sessionId}`, {
        method: 'DELETE',
        headers: getAuthHeaders(),
      });
      setSessions(prev => prev.filter(s => s.id !== sessionId));
    } catch {
      // best-effort
    }
  }, [dveId]);

  return {
    tools, sessions, loading, error,
    listTools, listSessions, installTool, spawnSession, terminateSession,
  };
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { X, ExternalLink, Loader2, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';

// Build the DVE page URL using the current origin so the request routes
// through KNIRVSERVER's /dve/* proxy → gateway → backend socket.
// No port scanning needed — the frontend and the /dve/ proxy share the same origin.
function buildDvePageUrl(dveId: string): string {
  return `/dve/${encodeURIComponent(dveId)}`;
}

interface DVEVerificationIframeProps {
  isOpen: boolean;
  onClose: () => void;
  dveId: string;
  dveName?: string;
}

export function DVEVerificationIframe({ isOpen, onClose, dveId, dveName }: DVEVerificationIframeProps) {
  const dvePageUrl = dveId ? buildDvePageUrl(dveId) : '';
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setLoading(true);
      setError(false);
    }
  }, [isOpen, dveId]);

  const retryConnection = useCallback(() => {
    setError(false);
    setLoading(true);
  }, []);

  const handleIframeMessage = useCallback((event: MessageEvent) => {
    // Listen for validation result messages from the DVE verification page
    if (event.data?.type === 'dve-validation-result') {
      // Validation complete — could show a toast or panel update
      console.log('[DVE Verification] Validation result:', event.data);
    }
  }, []);

  useEffect(() => {
    if (isOpen) {
      window.addEventListener('message', handleIframeMessage);
      return () => window.removeEventListener('message', handleIframeMessage);
    }
  }, [isOpen, handleIframeMessage]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-[#0a0f1e] overflow-hidden">
      {/* Header bar */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-purple-900/40 bg-[#0a0f1e]/95 backdrop-blur-sm shrink-0">
        <div className="flex items-center space-x-3">
          <Button variant="ghost" size="sm" onClick={onClose}>
            <svg className="w-4 h-4 mr-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M19 12H5m7-7-7 7 7 7" />
            </svg>
            Back
          </Button>
          <span className="text-sm font-medium text-purple-300">DVE Public Verification</span>
          {dveName && <Badge variant="outline" className="text-xs text-purple-400 border-purple-700">{dveName}</Badge>}
        </div>
        <div className="flex items-center space-x-1">
          <a href={dvePageUrl} target="_blank" rel="noopener noreferrer">
            <Button variant="ghost" size="sm" title="Open in browser">
              <ExternalLink className="w-4 h-4" />
            </Button>
          </a>
          <Button variant="ghost" size="sm" onClick={onClose} title="Close">
            <X className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {/* Content area */}
      <div className="flex-1 relative overflow-hidden">
        {loading && !dvePageUrl && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-[#0a0f1e] z-10">
            <Loader2 className="w-8 h-8 animate-spin text-purple-400" />
            <span className="text-sm text-purple-300">Connecting to gateway...</span>
          </div>
        )}

        {error && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-[#0a0f1e] z-10">
            <AlertCircle className="w-10 h-10 text-amber-400" />
            <div className="text-center space-y-1">
              <p className="text-sm font-medium text-amber-300">DVE page not available</p>
              <p className="text-xs text-muted-foreground">
                The KNIRVGATEWAY or KNIRVSERVER may not be running.
              </p>
            </div>
            <div className="flex gap-2">
              <Button size="sm" variant="outline" onClick={retryConnection}>Retry</Button>
              <a href={dvePageUrl} target="_blank" rel="noopener noreferrer">
                <Button size="sm" variant="ghost">
                  <ExternalLink className="w-3 h-3 mr-1" />
                  Open in browser
                </Button>
              </a>
            </div>
          </div>
        )}

        {dvePageUrl && !error && (
          <iframe
            src={dvePageUrl}
            className="w-full h-full border-0"
            title={`DVE Public Verification — ${dveName || dveId}`}
            sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
            onLoad={() => setLoading(false)}
            onError={() => { setLoading(false); setError(true); }}
          />
        )}

        {loading && dvePageUrl && (
          <div className="absolute top-0 left-0 right-0 flex items-center justify-center h-10 bg-[#0a0f1e]/80 z-10">
            <Loader2 className="w-4 h-4 animate-spin text-purple-400 mr-2" />
            <span className="text-xs text-purple-300">Loading DVE page...</span>
          </div>
        )}
      </div>
    </div>
  );
}

