56	      const resp = await fetch(`${API_BASE_URL}/api/v1/shell/sessions`, {
57	        method: 'POST',
58	        headers: getAuthHeaders(),
59	        body: JSON.stringify({ 
60	          command: 'terminal:start',
61	          node_id: nodeId,
62	          streaming: true 
63	        }),
64	      });
65	      if (!resp.ok) return false;
66	      const data = await resp.json();
67	      sessionIdRef.current = data.session_id;
68	      updateConnectionModeRef('knirvshell');
69	
70	      // Quick initial poll — if the session already closed (command failed
71	      // immediately), don't claim the connection; let the fallback chain
72	      // (KNIRVAGENT → SSH → local shell) try instead.
73	      const initResp = await fetch(
74	        `${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}`,
75	        { headers: getAuthHeaders() }
76	      );
77	      if (initResp.ok) {
78	        const initSess = await initResp.json();
79	        if (initSess.closed) {
80	          sessionIdRef.current = null;
81	          return false;
82	        }
83	      }
84	      
85	      term.writeln('\x1b[32m[CONNECTED] KNIRVCLI session established.\x1b[0m');
86	      term.write('\x1b[1;32m$ \x1b[0m');
87	
88	      // Poll for session output
89	      let lastOutputLen = 0;
90	      const pollOutput = async () => {
91	        if (!sessionIdRef.current) return;
92	        try {
93	          const outputResp = await fetch(
94	            `${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}`,
95	            { headers: getAuthHeaders() }
96	          );
97	          if (outputResp.ok) {
98	            const session = await outputResp.json();
99	            if (session.output && Array.isArray(session.output)) {
100	              // Only write new chunks since last poll
101	              const newChunks = session.output.slice(lastOutputLen);
102	              if (newChunks.length > 0) {
103	                term.write(newChunks.join(''));
104	                lastOutputLen = session.output.length;
105	              }
106	            }
107	            if (session.closed) {
108	              term.writeln('\x1b[33m[DISCONNECTED] Session closed.\x1b[0m');
109	              setSshConnected(false);
110	              if (pollIntervalRef.current) {
111	                clearInterval(pollIntervalRef.current);
112	              }
113	            }
114	          }
115	        } catch { /* ignore polling errors */ }
116	      };
117	
118	      pollIntervalRef.current = setInterval(pollOutput, 100);
119	      setSshConnected(true);
120	      return true;
121	    } catch {
122	      return false;
123	    }
124	  }, [nodeId]);
125	
126	  // Send input to KNIRVCLI session
127	  const sendToKNIRVCLI = useCallback(async (input: string) => {
128	    if (!sessionIdRef.current) return;
129	    try {
130	      await fetch(`${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}/input`, {
131	        method: 'POST',
132	        headers: getAuthHeaders(),
133	        body: JSON.stringify({ input }),
134	      });
135	    } catch { /* ignore send errors */ }
136	  }, []);
137	
138	  // Attempt to connect the terminal to the backend SSH WebSocket for the given node.
139	  const connectSSH = useCallback(async (term: XTermTerminal) => {
140	    if (!nodeId) return false;
141	    try {
142	      const resp = await fetch(`${API_BASE_URL}/api/dve/${nodeId}/ssh-session`, {
143	        method: 'POST',
144	        headers: getAuthHeaders(),
145	        body: JSON.stringify({ username: 'dve-admin' }),
146	      });
147	      if (!resp.ok) return false;
148	      const data = await resp.json();
149	      const wsProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
150	      const wsHost = window.location.host;
151	      const ws = new WebSocket(`${wsProto}//${wsHost}${data.ws_url}`);
152	      wsRef.current = ws;
153	      updateConnectionModeRef('ssh');
154	
155	      ws.onopen = () => {
156	        setSshConnected(true);
157	        term.writeln('\x1b[32m[CONNECTED] SSH tunnel established via TEE enclave.\x1b[0m');
158	        term.write('\x1b[1;32m$ \x1b[0m');
159	      };
160	      ws.onmessage = (ev) => {
161	        const msg = JSON.parse(ev.data);
162	        if (msg.type === 'data') term.write(msg.data);
163	      };
164	      ws.onerror = () => {
165	        setSshConnected(false);
166	        term.writeln('\x1b[31m[SSH] Connection error — falling back to local shell.\x1b[0m');
167	      };
168	      ws.onclose = () => {
169	        setSshConnected(false);
170	      };
171	      return true;
172	    } catch {
173	      return false;
174	    }
175	  }, [nodeId]);
176	
177	  // Attempt to connect the terminal to the DVE Supervisor Agent (KNIRVAGENT).
178	  const connectKNIRVAGENT = useCallback(async (term: XTermTerminal) => {
179	    if (!nodeId) return false;
180	    try {
181	      const resp = await fetch(`${API_BASE_URL}/api/dve/${nodeId}/supervisor-agent/session`, {
182	        headers: getAuthHeaders(),
183	      });
184	      if (!resp.ok) return false;
185	      const data = await resp.json();
186	      const wsProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
187	      const wsHost = window.location.host;
188	      const ws = new WebSocket(`${wsProto}//${wsHost}${data.ws_url}`);
189	      wsRef.current = ws;
190	      updateConnectionModeRef('knirvagent');
191	
192	      ws.onopen = () => {
193	        setSshConnected(true);
194	        term.writeln('\x1b[35m[CONNECTED] DVE Supervisor Agent (KNIRVAGENT) link established.\x1b[0m');
195	        term.writeln('\x1b[35m[INFO] Your terminal input will be relayed to the KNIRVAGENT supervisor.\x1b[0m');
196	        term.write('\x1b[1;35magent> \x1b[0m');
197	      };
198	      ws.onmessage = (ev) => {
199	        const msg = JSON.parse(ev.data);
200	        if (msg.type === 'data') {
201	          if (agentProcessingRef.current) {
202	            term.write('\r\x1b[2K');
203	            agentProcessingRef.current = false;
204	          }
205	          term.write(msg.data);
206	        } else if (msg.type === 'prompt') {
207	          if (agentProcessingRef.current) {
208	            term.write('\r\x1b[2K');
209	            agentProcessingRef.current = false;
210	          }
211	          term.write('\x1b[1;35magent> \x1b[0m');
212	        }
213	      };
214	      ws.onerror = () => {
215	        setSshConnected(false);
216	        term.writeln('\x1b[33m[KNIRVAGENT] Connection unavailable — trying SSH fallback.\x1b[0m');
217	      };
218	      ws.onclose = () => {
219	        setSshConnected(false);
220	      };
221	      return true;
222	    } catch {
223	      return false;
224	    }
225	  }, [nodeId]);
226	
227	  const loadRealLogs = useCallback(async () => {
228	    if (!fabricId || !xtermRef.current) return;
229	    
230	    try {
231	      const logs = await fetchFabricLogs(fabricId, 50);
232	      if (logs && logs.length > 0) {
