304	
305	        term.onData((data) => {
306	          // Route input to appropriate backend based on connection mode (via ref to avoid stale closure)
307	          const mode = connectionModeRef.current;
308	          if (mode === 'knirvshell' && sessionIdRef.current) {
309	            // Buffer input and send complete lines on Enter
310	            inputBufferRef.current += data;
311	            if (data === '\r') {
312	              const line = inputBufferRef.current.replace(/\r/g, '').trim();
313	              inputBufferRef.current = '';
314	              if (line) {
315	                sendToKNIRVCLI(line + '\n');
316	              }
