42	<div class="container">
43	    <header>
44	        <h1>DVE: {{ .DVEID }} <span class="badge">{{ .Status }}</span></h1>
45	    </header>
46	
47	    <!-- Public Validation Prompt -->
48	    <div class="validation-prompt">
49	        <h2>Public Validation</h2>
50	        <p>Verify this DVE's integrity. Generate a signed, timestamped validation report for <strong>1 NRN</strong>.</p>
51	
52	        <div class="wallet-section">
53	            <button id="connect-btn" onclick="connectWallet()">Connect Wallet</button>
54	            <span id="wallet-address"></span>
55	        </div>
56	
57	        <div class="validation-input-section">
58	            <textarea id="validation-input" placeholder="Optional: provide context or input for the validation..."></textarea>
59	            <button id="validate-btn" onclick="initiateValidation()" disabled>
60	                Initiate Validation &mdash; 1 NRN
61	            </button>
62	        </div>
63	
64	        <div id="proof-result"></div>
65	    </div>
66	
67	    <div class="content">
68	        <div class="main-panel">
69	            {{ template "validation_records" . }}
70	        </div>
71	        <div class="sidebar">
72	            {{ template "metrics_panel" . }}
73	        </div>
74	    </div>
75	</div>
76	
77	<script>
78	// Wallet connection and validation initiation for public DVE verification
79	let connectedWallet = '';
80	function truncateWallet(a) { if (!a||a.length<10) return a; return a.substring(0,6)+'...'+a.substring(a.length-4); }
81	async function connectWallet() {
82	    if (!window.ethereum) { alert('Please install MetaMask to verify this DVE.'); return; }
83	    try {
84	        const acc = await window.ethereum.request({method:'eth_requestAccounts'});
85	        connectedWallet = acc[0];
86	        document.getElementById('wallet-address').textContent = truncateWallet(connectedWallet);
87	        document.getElementById('connect-btn').textContent = 'Connected';
88	        document.getElementById('validate-btn').disabled = false;
89	    } catch(e) { alert('Failed to connect wallet: '+e.message); }
90	}
91	async function initiateValidation() {
92	    if (!connectedWallet||!window.ethereum) { alert('Connect wallet first.'); return; }
93	    const btn=document.getElementById('validate-btn'), pr=document.getElementById('proof-result'),
94	          input=document.getElementById('validation-input').value;
95	    btn.disabled=true; btn.textContent='Processing...'; pr.innerHTML='<p style="color:#666;">Sending transaction...</p>';
96	    try {
97	        const txHash = await window.ethereum.request({
98	            method:'eth_sendTransaction',
99	            params:[{to:'{{ .RewardPoolAddress }}',value:'0x'+(1n*10n**18n).toString(16),gas:'0x5208'}]
100	        });
101	        pr.innerHTML='<p style="color:#666;">Tx sent. Waiting for backend...</p>';
102	        const resp=await fetch('/dve/{{ .DVEID }}/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({signed_tx:txHash,wallet_address:connectedWallet,payload:input})});
103	        if(!resp.ok){const e=await resp.json().catch(()=>({}));throw new Error(e.error||'HTTP '+resp.status);}
104	        const r=await resp.json();
105	        pr.innerHTML='<div class="receipt"><h3>Validation Initiated</h3><p><strong>Session:</strong> '+(r.session_id||'')+'</p><p><strong>Proof:</strong> '+(r.proof||'generating...')+'</p><p><strong>Timestamp:</strong> '+(r.timestamp||new Date().toISOString())+'</p></div>';
106	        window.parent.postMessage({type:'dve:validation:complete',dveId:'{{ .DVEID }}',sessionId:r.session_id,proof:r.proof,timestamp:r.timestamp},'*');
107	    } catch(e) { pr.innerHTML='<p style="color:#f44336;font-size:13px;">Error: '+e.message+'</p>'; }
108	    finally { btn.disabled=false; btn.textContent='Initiate Validation \u2014 1 NRN'; }
109	}
110	if(window.ethereum){window.ethereum.request({method:'eth_accounts'}).then(function(a){if(a.length>0){connectedWallet=a[0];document.getElementById('wallet-address').textContent=truncateWallet(connectedWallet);document.getElementById('connect-btn').textContent='Connected';document.getElementById('validate-btn').disabled=false;}}).catch(function(){});}
111	</script>
112	{{ end }}
