	if idx := strings.Index(trimmed, "/inner"); idx != -1 {
		dveID := trimmed[:idx]
		innerRest := trimmed[idx+len("/inner"):]
		c.Request.URL.Path = "/api/agent/" + dveID + "/api/inner" + innerRest
		c.Request.URL.RawPath = ""
		innerProxy, innerErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
		if innerErr == nil {
			innerProxy.ServeHTTP(c.Writer, c.Request)
			return
		}
	}
}

