1	package web
2	
3	import (
4		"io"
5		"log"
6		"net/http"
7	
8		"github.com/gorilla/mux"
9	)
10	
11	type InnerAgentManagerProxy interface {
12		ForwardToInnerAgent(dveID, method, path string, body io.Reader) (*http.Response, error)
13		GetSocketPath(dveID string) (string, error)
14	}
15	
16	type InnerAgentHandlers struct {
17		proxy InnerAgentManagerProxy
18	}
19	
20	func NewInnerAgentHandlers(proxy InnerAgentManagerProxy) *InnerAgentHandlers {
21		return &InnerAgentHandlers{proxy: proxy}
22	}
23	
24	func (h *InnerAgentHandlers) RegisterRoutes(r *mux.Router) {
25		sub := r.PathPrefix("/api/v1/dve/{dveId}/inner").Subrouter()
26		sub.HandleFunc("/spawn", h.HandleSpawn).Methods("POST", "OPTIONS")
27		sub.HandleFunc("/install", h.HandleInstall).Methods("POST", "OPTIONS")
28		sub.HandleFunc("/sessions", h.HandleListSessions).Methods("GET", "OPTIONS")
29		sub.HandleFunc("/tools", h.HandleListTools).Methods("GET", "OPTIONS")
30		sub.HandleFunc("/sessions/{sessionId}", h.HandleSessionAction).Methods("DELETE", "GET", "OPTIONS")
31		sub.HandleFunc("/sessions/{sessionId}/input", h.HandleSessionInput).Methods("POST", "OPTIONS")
32		sub.HandleFunc("/sessions/{sessionId}/log", h.HandleSessionLog).Methods("GET", "OPTIONS")
33	}
34	
35	func (h *InnerAgentHandlers) forward(w http.ResponseWriter, r *http.Request, dveID, innerPath string) {
36		resp, err := h.proxy.ForwardToInnerAgent(dveID, r.Method, innerPath, r.Body)
37		if err != nil {
38			log.Printf("[InnerAgent] Forward error DVE=%s path=%s: %v", dveID, innerPath, err)
39			http.Error(w, err.Error(), http.StatusBadGateway)
40			return
41		}
42		defer resp.Body.Close()
43	
44		for k, vv := range resp.Header {
45			for _, v := range vv {
46				w.Header().Add(k, v)
47			}
48		}
49		w.Header().Del("Access-Control-Allow-Origin")
50		w.WriteHeader(resp.StatusCode)
51		io.Copy(w, resp.Body)
52	}
53	
54	func (h *InnerAgentHandlers) HandleSpawn(w http.ResponseWriter, r *http.Request) {
55		dveID := mux.Vars(r)["dveId"]
56		h.forward(w, r, dveID, "/api/inner/spawn")
57	}
58	
59	func (h *InnerAgentHandlers) HandleInstall(w http.ResponseWriter, r *http.Request) {
60		dveID := mux.Vars(r)["dveId"]
61		h.forward(w, r, dveID, "/api/inner/install")
62	}
63	
64	func (h *InnerAgentHandlers) HandleListSessions(w http.ResponseWriter, r *http.Request) {
65		dveID := mux.Vars(r)["dveId"]
66		h.forward(w, r, dveID, "/api/inner/sessions")
67	}
68	
69	func (h *InnerAgentHandlers) HandleListTools(w http.ResponseWriter, r *http.Request) {
70		dveID := mux.Vars(r)["dveId"]
71		h.forward(w, r, dveID, "/api/inner/tools")
72	}
73	
74	func (h *InnerAgentHandlers) HandleSessionAction(w http.ResponseWriter, r *http.Request) {
75		dveID := mux.Vars(r)["dveId"]
76		sessionID := mux.Vars(r)["sessionId"]
77		innerPath := "/api/inner/" + sessionID
78		h.forward(w, r, dveID, innerPath)
79	}
80	
81	func (h *InnerAgentHandlers) HandleSessionInput(w http.ResponseWriter, r *http.Request) {
82		dveID := mux.Vars(r)["dveId"]
83		sessionID := mux.Vars(r)["sessionId"]
84		innerPath := "/api/inner/" + sessionID + "/input"
85		h.forward(w, r, dveID, innerPath)
86	}
87	
88	func (h *InnerAgentHandlers) HandleSessionLog(w http.ResponseWriter, r *http.Request) {
89		dveID := mux.Vars(r)["dveId"]
90		sessionID := mux.Vars(r)["sessionId"]
91		innerPath := "/api/inner/" + sessionID + "/log"
92		h.forward(w, r, dveID, innerPath)
93	}
94	
95	func (h *InnerAgentHandlers) HandleSessionStream(w http.ResponseWriter, r *http.Request) {
96		dveID := mux.Vars(r)["dveId"]
97		sessionID := mux.Vars(r)["sessionId"]
98	
99		w.Header().Set("Content-Type", "application/octet-stream")
100		w.Header().Set("Transfer-Encoding", "chunked")
101		w.Header().Set("X-Accel-Buffering", "no")
102		w.WriteHeader(http.StatusOK)
103		flusher, _ := w.(http.Flusher)
104	
105		resp, err := h.proxy.ForwardToInnerAgent(dveID, "GET", "/api/inner/"+sessionID+"/stream", nil)
106		if err != nil {
107			http.Error(w, err.Error(), http.StatusBadGateway)
108			return
109		}
110		defer resp.Body.Close()
111	
112		buf := make([]byte, 4096)
113		for {
114			n, err := resp.Body.Read(buf)
115			if n > 0 {
116				if _, writeErr := w.Write(buf[:n]); writeErr != nil {
117					return
118				}
119				if flusher != nil {
120					flusher.Flush()
121				}
122			}
123			if err != nil {
124				return
125			}
126		}
127	}
