// Propagate paths to bundled binaries so the backend does not rely on CWD
// or system PATH to locate knirvgateway and knirvshell.  Also propagate the
// app data directory so the gateway runtime extracts files there instead of
// /tmp, and so the backend can locate config/log directories consistently.
if appDataDir, err := getAppDataDir(); err == nil {
	binDir := filepath.Join(appDataDir, "bin")
	env = append(env,
		fmt.Sprintf("KNIRV_APP_DATA_DIR=%s", appDataDir),
		fmt.Sprintf("KNIRV_GATEWAY_BINARY_PATH=%s", filepath.Join(binDir, "knirvgateway")),
		fmt.Sprintf("KNIRV_GATEWAY_BINARY_DIR=%s", binDir),
		fmt.Sprintf("KNIRV_CHAIN_BINARY_DIR=%s", binDir),
		fmt.Sprintf("KNIRV_GRAPH_BINARY_DIR=%s", binDir),
		fmt.Sprintf("KNIRV_ORACLE_BINARY_DIR=%s", binDir),
		fmt.Sprintf("KNIRV_KNIRVCLI_PATH=%s", filepath.Join(binDir, "knirvshell")),
	)
}
if configDir, err := getConfigDir(); err == nil {
	env = append(env, fmt.Sprintf("KNIRV_CONFIG_DIR=%s", configDir))
}

// Pass the project log directory as an absolute path so the backend writes
// logs to <cwd>/logs/server.log regardless of where the backend binary runs from.
if cwd, err := os.Getwd(); err == nil {
	env = append(env, fmt.Sprintf("KNIRV_PROJECT_LOG_DIR=%s", filepath.Join(cwd, "logs")))
}

// Add testnet environment variable if enabled
if app.config.Testnet {
	env = append(env,
		"KNIRV_TESTNET=true",
		"KNIRV_SECURITY_AUTH_REQUIRED=false",
		"KNIRV_MODE=headless",
	)
	log.Println("Starting backend in testnet mode with simplified security")
}

// Propagate ORACLE_KEY_PASSWORD from the parent environment so the
// backend_server subprocess can decrypt root.key without needing an
// interactive terminal.  Without this the backend silently skips all
// root.key secrets (API keys for Gemini, DeepSeek, Cerebras, etc.).
if pwd := os.Getenv("ORACLE_KEY_PASSWORD"); pwd != "" {
	env = append(env, fmt.Sprintf("ORACLE_KEY_PASSWORD=%s", pwd))
}

'use client';

import { useState, useCallback } from 'react';
import { API_BASE_URL, getAuthHeaders } from '@/lib/api';

export interface InnerAgentTool {
  name: string;
  binary: string;
  is_installed: boolean;
}

export interface InnerAgentSession {
  id: string;
  tool_name: string;
  status: 'running' | 'exited';
  started_at: string;
}

export function useInnerAgent(dveId: string | undefined) {
  const [tools, setTools] = useState<InnerAgentTool[]>([]);
  const [sessions, setSessions] = useState<InnerAgentSession[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const listTools = useCallback(async () => {
    if (!dveId) return;
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/tools`, {
        headers: getAuthHeaders(),
      });
      if (resp.ok) {
        const data = await resp.json();
        setTools(Array.isArray(data) ? data : data.tools ?? []);
      }
    } catch (err) {
      setError(String(err));
    }
  }, [dveId]);

  const listSessions = useCallback(async () => {
    if (!dveId) return;
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/sessions`, {
        headers: getAuthHeaders(),
      });
      if (resp.ok) {
        const data = await resp.json();
        setSessions(Array.isArray(data) ? data : data.sessions ?? []);
      }
    } catch (err) {
      setError(String(err));
    }
  }, [dveId]);

  const installTool = useCallback(async (toolName: string): Promise<boolean> => {
    if (!dveId) return false;
    setLoading(true);
    setError(null);
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/install`, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify({ tool: toolName }),
      });
      if (!resp.ok) {
        const body = await resp.text();
        setError(`Install failed: ${body}`);
        return false;
      }
      await listTools();
      return true;
    } catch (err) {
      setError(String(err));
      return false;
    } finally {
      setLoading(false);
    }
  }, [dveId, listTools]);

  const spawnSession = useCallback(async (toolName: string): Promise<string | null> => {
    if (!dveId) return null;
    setLoading(true);
    setError(null);
    try {
      const resp = await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/spawn`, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify({ tool: toolName }),
      });
      if (!resp.ok) {
        const body = await resp.text();
        setError(`Spawn failed: ${body}`);
        return null;
      }
      const data = await resp.json();
      const sessionId: string = data.id ?? data.session_id;
      if (sessionId) {
        setSessions(prev => [...prev, {
          id: sessionId,
          tool_name: toolName,
          status: 'running',
          started_at: new Date().toISOString(),
        }]);
      }
      return sessionId ?? null;
    } catch (err) {
      setError(String(err));
      return null;
    } finally {
      setLoading(false);
    }
  }, [dveId]);

  const terminateSession = useCallback(async (sessionId: string) => {
    if (!dveId) return;
    try {
      await fetch(`${API_BASE_URL}/api/v1/dve/${dveId}/inner/sessions/${sessionId}`, {
        method: 'DELETE',
        headers: getAuthHeaders(),
      });
      setSessions(prev => prev.filter(s => s.id !== sessionId));
    } catch {
      // best-effort
    }
  }, [dveId]);

  return {
    tools, sessions, loading, error,
    listTools, listSessions, installTool, spawnSession, terminateSession,
  };
}

