137	
138	  // Attempt to connect the terminal to the backend SSH WebSocket for the given node.
139	  const connectSSH = useCallback(async (term: XTermTerminal) => {
140	    if (!nodeId) return false;
141	    try {
142	      const resp = await fetch(`${API_BASE_URL}/api/dve/${nodeId}/ssh-session`, {
143	        method: 'POST',
144	        headers: getAuthHeaders(),
145	        body: JSON.stringify({ username: 'dve-admin' }),
146	      });
147	      if (!resp.ok) return false;
148	      const data = await resp.json();
149	      const wsProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
150	      const wsHost = window.location.host;
151	      const ws = new WebSocket(`${wsProto}//${wsHost}${data.ws_url}`);
152	      wsRef.current = ws;
153	      updateConnectionModeRef('ssh');
154	
155	      ws.onopen = () => {
156	        setSshConnected(true);
157	        term.writeln('\x1b[32m[CONNECTED] SSH tunnel established via TEE enclave.\x1b[0m');
158	        term.write('\x1b[1;32m$ \x1b[0m');
159	      };
160	      ws.onmessage = (ev) => {
161	        const msg = JSON.parse(ev.data);
162	        if (msg.type === 'data') term.write(msg.data);
163	      };
164	      ws.onerror = () => {
165	        setSshConnected(false);
166	        term.writeln('\x1b[31m[SSH] Connection error — falling back to local shell.\x1b[0m');
167	      };
168	      ws.onclose = () => {
169	        setSshConnected(false);
170	      };
171	      return true;
172	    } catch {
173	      return false;
174	    }
175	  }, [nodeId]);
176	
177	  // Attempt to connect the terminal to the DVE Supervisor Agent (KNIRVAGENT).
178	  const connectKNIRVAGENT = useCallback(async (term: XTermTerminal) => {
179	    if (!nodeId) return false;
180	    try {
181	      const resp = await fetch(`${API_BASE_URL}/api/dve/${nodeId}/supervisor-agent/session`, {
182	        headers: getAuthHeaders(),
183	      });
184	      if (!resp.ok) return false;
185	      const data = await resp.json();
186	      const wsProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
187	      const wsHost = window.location.host;
188	      const ws = new WebSocket(`${wsProto}//${wsHost}${data.ws_url}`);
189	      wsRef.current = ws;
190	      updateConnectionModeRef('knirvagent');
191	
192	      ws.onopen = () => {
193	        setSshConnected(true);
194	        term.writeln('\x1b[35m[CONNECTED] DVE Supervisor Agent (KNIRVAGENT) link established.\x1b[0m');
195	        term.writeln('\x1b[35m[INFO] Your terminal input will be relayed to the KNIRVAGENT supervisor.\x1b[0m');
196	        term.write('\x1b[1;35magent> \x1b[0m');
197	      };
198	      ws.onmessage = (ev) => {
199	        const msg = JSON.parse(ev.data);
200	        if (msg.type === 'data') {
201	          if (agentProcessingRef.current) {
202	            term.write('\r\x1b[2K');
203	            agentProcessingRef.current = false;
204	          }
205	          term.write(msg.data);
206	        } else if (msg.type === 'prompt') {
207	          if (agentProcessingRef.current) {
208	            term.write('\r\x1b[2K');
209	            agentProcessingRef.current = false;
210	          }
211	          term.write('\x1b[1;35magent> \x1b[0m');
212	        }
213	      };
214	      ws.onerror = () => {
215	        setSshConnected(false);
216	        term.writeln('\x1b[33m[KNIRVAGENT] Connection unavailable — trying SSH fallback.\x1b[0m');
217	      };
218	      ws.onclose = () => {
219	        setSshConnected(false);
220	      };
221	      return true;
222	    } catch {
223	      return false;
224	    }
225	  }, [nodeId]);
226	
227	  const loadRealLogs = useCallback(async () => {
228	    if (!fabricId || !xtermRef.current) return;
229	    
230	    try {
231	      const logs = await fetchFabricLogs(fabricId, 50);
232	      if (logs && logs.length > 0) {
233	        xtermRef.current.writeln('\x1b[32m[SYSTEM] Fetching historical logs from Fabric ID: ' + fabricId + '\x1b[0m');
234	        logs.forEach(log => {
235	          const timestamp = new Date(log.timestamp).toLocaleTimeString();
236	          const color = log.level === 'error' ? '\x1b[31m' : log.level === 'warn' ? '\x1b[33m' : '\x1b[32m';
237	          xtermRef.current?.writeln(`[${timestamp}] ${color}${log.level.toUpperCase()}\x1b[0m: ${log.message}`);
238	        });
239	      }
240	    } catch (err) {
241	      xtermRef.current?.writeln('\x1b[31m[ERROR] Failed to fetch historical logs.\x1b[0m');
242	    }
243	  }, [fabricId, fetchFabricLogs]);
244	
245	  useEffect(() => {
246	    if (isOpen && terminalRef.current && !xtermRef.current) {
247	      setIsInitializing(true);
248	      
249	      // Dynamically import and initialize terminal
250	      const initTerminal = async () => {
251	        const { Terminal } = await import('@xterm/xterm');
252	        const { FitAddon } = await import('@xterm/addon-fit');
253	        const { WebLinksAddon } = await import('@xterm/addon-web-links');
254	
255	        const term = new Terminal({
256	          cursorBlink: true,
257	          fontSize: 11,
258	          fontFamily: 'Menlo, Monaco, "Courier New", monospace',
259	          theme: {
260	            background: '#03050a',
261	            foreground: '#93c5fd',
262	            cursor: '#2563eb',
263	            selectionBackground: 'rgba(37, 99, 235, 0.3)',
264	          },
265	          convertEol: true,
266	        });
267	
268	        const fitAddon = new FitAddon();
269	        const webLinksAddon = new WebLinksAddon();
270	
271	        term.loadAddon(fitAddon);
272	        term.loadAddon(webLinksAddon);
273	
274	        if (terminalRef.current) {
275	          term.open(terminalRef.current);
276	          fitAddon.fit();
277	        }
278	        fitAddon.fit();
279	
280	        term.writeln('\x1b[1;34mKNIRV-SERVER Secure Terminal v1.1.0\x1b[0m');
281	        term.writeln(`\x1b[33mConnecting to context: ${nodeId || 'global'}...\x1b[0m`);
282	        term.writeln('\x1b[32mAuthenticated via Hardware TEE Enclave.\x1b[0m');
283	        term.writeln('');
284	
285	        xtermRef.current = term;
286	        fitAddonRef.current = fitAddon;
287	
288	        setIsInitializing(false);
289	
290	        // Connection priority: KNIRVAGENT supervisor -> SSH -> KNIRVCLI -> local
291	        // KNIRVAGENT is the primary DVE supervisor terminal — try it first.
292	        let didConnect = await connectKNIRVAGENT(term);
293	        if (!didConnect) {
294	          didConnect = await connectSSH(term);
295	        }
296	        if (!didConnect) {
297	          didConnect = await connectKNIRVCLI(term);
298	        }
299	        if (!didConnect) {
300	          term.writeln('\x1b[33m[FALLBACK] No remote connection available — using local simulation.\x1b[0m');
301	          term.write('\x1b[1;32mroot@fabric-server:~# \x1b[0m');
302	          loadRealLogs();
303	        }
304	
305	        term.onData((data) => {
306	          // Route input to appropriate backend based on connection mode (via ref to avoid stale closure)
307	          const mode = connectionModeRef.current;
308	          if (mode === 'knirvshell' && sessionIdRef.current) {
309	            // Buffer input and send complete lines on Enter
310	            inputBufferRef.current += data;
311	            if (data === '\r') {
312	              const line = inputBufferRef.current.replace(/\r/g, '').trim();
313	              inputBufferRef.current = '';
314	              if (line) {
315	                sendToKNIRVCLI(line + '\n');
316	              }
317	              term.write('\r\n');
318	            } else if (data === '\u007f') { // Backspace
319	              if (inputBufferRef.current.length > 1) {
320	                inputBufferRef.current = inputBufferRef.current.slice(0, -2); // remove both the backspace char and the preceding char
321	                term.write('\b \b');
322	              } else {
323	                inputBufferRef.current = '';
324	              }
325	            } else {
326	              term.write(data);
327	            }
328	          } else if (mode === 'knirvagent' && wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
329	            // Buffer input for KNIRVAGENT and send complete lines on Enter
330	            inputBufferRef.current += data;
331	            if (data === '\r') {
332	              const line = inputBufferRef.current.replace(/\r/g, '').trim();
333	              inputBufferRef.current = '';
334	              if (line) {
335	                wsRef.current.send(JSON.stringify({ type: 'input', data: line }));
336	                term.write('\r\n\x1b[33m⟳ Processing...\x1b[0m');
337	                agentProcessingRef.current = true;
338	              } else {
339	                term.write('\r\n');
340	              }
341	            } else if (data === '\u007f') { // Backspace
342	              if (inputBufferRef.current.length > 1) {
343	                inputBufferRef.current = inputBufferRef.current.slice(0, -2);
344	                term.write('\b \b');
345	              } else {
346	                inputBufferRef.current = '';
347	              }
348	            } else {
349	              term.write(data);
350	            }
351	          } else if (mode === 'ssh' && wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
352	            wsRef.current.send(JSON.stringify({ type: 'input', data }));
353	          } else {
354	            // Local simulation fallback
355	            if (data === '\r') {
356	              term.write('\r\n\x1b[1;32mroot@fabric-server:~# \x1b[0m');
357	            } else if (data === '\u007f') {
358	              term.write('\b \b');
359	            } else {
360	              term.write(data);
361	            }
362	          }
363	        });
364	
365	        const handleResize = () => fitAddon.fit();
366	        window.addEventListener('resize', handleResize);
367	
368	        return () => {
369	          window.removeEventListener('resize', handleResize);
370	          if (pollIntervalRef.current) {
371	            clearInterval(pollIntervalRef.current);
372	          }
373	          if (sessionIdRef.current) {
374	            fetch(`${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}/stop`, {
375	              method: 'POST',
376	              headers: getAuthHeaders(),
377	            }).catch(() => {});
378	          }
379	          if (wsRef.current) {
380	            wsRef.current.close();
381	            wsRef.current = null;
382	          }
383	          term.dispose();
384	          xtermRef.current = null;
385	        };
386	      };
387	
388	      let cleanup: (() => void) | undefined;
389	      initTerminal().then((c) => { cleanup = c; });
390	
391	      return () => {
392	        if (cleanup) cleanup();
393	      };
394	    }
395	  }, [isOpen, nodeId, loadRealLogs, connectSSH]);
396	
397	  if (!isOpen) return null;
398	
399	  return (
400	    <div
401	      className="absolute z-[100] transition-slide duration-500 ease-in-out bg-slate-950 border border-blue-600/50 shadow-[0_0_40px_rgba(0,0,0,0.7)] overflow-hidden rounded-xl animate-in fade-in zoom-in-95 gpu-accelerated"
402	      style={{
403	        right: isMonitorOpen ? '40px' : '20px',
404	        top: isMonitorOpen ? '20px' : '80px',
405	        width: isMonitorOpen ? '500px' : '600px',
406	        height: isMonitorOpen ? '300px' : '400px',
407	      }}
408	    >
409	      <div className="h-full flex flex-col">
410	        {/* Header */}
411	        <div className="flex items-center justify-between px-3 py-2 border-b border-blue-600/30 bg-slate-900/80 backdrop-blur-md shrink-0">
412	          <div className="flex items-center space-x-2">
413	            <div className="relative">
414	              <LucideTerminal className="w-4 h-4 text-blue-400" />
415	              <div className="absolute -top-1 -right-1 w-2 h-2 bg-green-500 rounded-full animate-pulse" />
416	            </div>
417	            <h2 className="text-[11px] font-black uppercase tracking-tighter text-blue-100">
418	              Terminal
419	            </h2>
420	            <p className="text-[9px] font-mono text-slate-500 hidden sm:block">Node: {nodeId || 'Distributed'}</p>
421	          </div>
422	          <div className="flex items-center space-x-2">
423	            <button
424	              onClick={loadRealLogs}
425	              className="text-slate-500 hover:text-blue-400 p-1 transition-colors"
426	              title="Sync Logs"
427	            >
428	              <RefreshCw className="w-3.5 h-3.5" />
429	            </button>
430	            <div className="h-4 w-px bg-slate-800 mx-1" />
431	            <button
432	              onClick={onClose}
433	              className="text-slate-500 hover:text-white hover:bg-red-900/30 p-1 rounded transition-interactive"
434	            >
435	              <X className="w-4 h-4" />
436	            </button>
437	          </div>
438	        </div>
439	
440	        {/* Tab bar */}
441	        <div className="flex items-center border-b border-slate-800 bg-slate-950/80 overflow-x-auto shrink-0">
442	          {/* Supervisor tab */}
443	          <button
444	            onClick={() => setActiveTab('supervisor')}
445	            className={`flex items-center gap-1.5 px-3 py-1.5 text-[11px] font-medium whitespace-nowrap border-r border-slate-800 transition-colors ${
446	              activeTab === 'supervisor'
447	                ? 'bg-[#03050a] text-blue-300 border-b-2 border-b-blue-500 -mb-px'
448	                : 'text-slate-500 hover:text-slate-300 hover:bg-slate-900/50'
449	            }`}
450	          >
451	            <LucideTerminal className="w-3 h-3" />
452	            Supervisor
453	          </button>
454	
455	          {/* Inner agent session tabs */}
456	          {innerSessions.map(sess => (
457	            <button
458	              key={sess.sessionId}
459	              onClick={() => setActiveTab(sess.sessionId)}
460	              className={`flex items-center gap-1.5 px-3 py-1.5 text-[11px] font-medium whitespace-nowrap border-r border-slate-800 group transition-colors ${
461	                activeTab === sess.sessionId
462	                  ? 'bg-[#03050a] text-purple-300 border-b-2 border-b-purple-500 -mb-px'
463	                  : 'text-slate-500 hover:text-slate-300 hover:bg-slate-900/50'
464	              }`}
465	            >
466	              <Play className="w-2.5 h-2.5" />
467	              {sess.toolName}
468	              <span
469	                role="button"
470	                tabIndex={0}
471	                onClick={e => {
472	                  e.stopPropagation();
473	                  setInnerSessions(prev => prev.filter(s => s.sessionId !== sess.sessionId));
474	                  if (activeTab === sess.sessionId) setActiveTab('supervisor');
475	                }}
476	                onKeyDown={e => { if (e.key === 'Enter') { e.stopPropagation(); setInnerSessions(prev => prev.filter(s => s.sessionId !== sess.sessionId)); if (activeTab === sess.sessionId) setActiveTab('supervisor'); } }}
477	                className="opacity-0 group-hover:opacity-100 ml-0.5 hover:text-red-400 transition-opacity"
478	                title="Close tab"
479	              >
480	                <X className="w-2.5 h-2.5" />
481	              </span>
482	            </button>
483	          ))}
484	
485	          {/* Spawn new terminal session */}
486	          <button
487	            onClick={async () => {
488	              const sessionId = await spawnSession('shell');
489	              if (sessionId) {
490	                const label = `Terminal ${innerSessions.length + 1}`;
491	                setInnerSessions(prev => [...prev, { sessionId, toolName: label }]);
492	                setActiveTab(sessionId);
493	              }
494	            }}
495	            className="flex items-center gap-1 px-3 py-1.5 text-[11px] text-slate-500 hover:text-purple-300 hover:bg-slate-900/50 transition-colors whitespace-nowrap"
496	            title="New terminal"
497	          >
498	            <Plus className="w-3 h-3" />
499	          </button>
500	        </div>
501	
502	        {/* Terminal content */}
503	        <div className="flex-1 bg-[#03050a] overflow-hidden relative">
504	          {/* Supervisor xterm — always mounted, hidden when not active */}
505	          <div
506	            className="absolute inset-0 p-3"
507	            style={{ display: activeTab === 'supervisor' ? 'block' : 'none' }}
508	          >
509	            <div ref={terminalRef} className="h-full w-full custom-scrollbar" />
510	            {isInitializing && (
511	              <div className="absolute inset-0 bg-black/80 flex items-center justify-center backdrop-blur-sm">
