package web

import (
	"io"
	"log"
	"net/http"

	"github.com/gorilla/mux"
)

type InnerAgentManagerProxy interface {
	ForwardToInnerAgent(dveID, method, path string, body io.Reader) (*http.Response, error)
	GetSocketPath(dveID string) (string, error)
}

type InnerAgentHandlers struct {
	proxy InnerAgentManagerProxy
}

func NewInnerAgentHandlers(proxy InnerAgentManagerProxy) *InnerAgentHandlers {
	return &InnerAgentHandlers{proxy: proxy}
}

func (h *InnerAgentHandlers) RegisterRoutes(r *mux.Router) {
	sub := r.PathPrefix("/api/v1/dve/{dveId}/inner").Subrouter()
	sub.HandleFunc("/spawn", h.HandleSpawn).Methods("POST", "OPTIONS")
	sub.HandleFunc("/install", h.HandleInstall).Methods("POST", "OPTIONS")
	sub.HandleFunc("/sessions", h.HandleListSessions).Methods("GET", "OPTIONS")
	sub.HandleFunc("/tools", h.HandleListTools).Methods("GET", "OPTIONS")
	sub.HandleFunc("/sessions/{sessionId}", h.HandleSessionAction).Methods("DELETE", "GET", "OPTIONS")
	sub.HandleFunc("/sessions/{sessionId}/input", h.HandleSessionInput).Methods("POST", "OPTIONS")
	sub.HandleFunc("/sessions/{sessionId}/log", h.HandleSessionLog).Methods("GET", "OPTIONS")
}

func (h *InnerAgentHandlers) forward(w http.ResponseWriter, r *http.Request, dveID, innerPath string) {
	resp, err := h.proxy.ForwardToInnerAgent(dveID, r.Method, innerPath, r.Body)
	if err != nil {
		log.Printf("[InnerAgent] Forward error DVE=%s path=%s: %v", dveID, innerPath, err)
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	for k, vv := range resp.Header {
		for _, v := range vv {
			w.Header().Add(k, v)
		}
	}
	w.Header().Del("Access-Control-Allow-Origin")
	w.WriteHeader(resp.StatusCode)
	io.Copy(w, resp.Body)
}

func (h *InnerAgentHandlers) HandleSpawn(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	h.forward(w, r, dveID, "/api/inner/spawn")
}

func (h *InnerAgentHandlers) HandleInstall(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	h.forward(w, r, dveID, "/api/inner/install")
}

func (h *InnerAgentHandlers) HandleListSessions(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	h.forward(w, r, dveID, "/api/inner/sessions")
}

func (h *InnerAgentHandlers) HandleListTools(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	h.forward(w, r, dveID, "/api/inner/tools")
}

func (h *InnerAgentHandlers) HandleSessionAction(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	sessionID := mux.Vars(r)["sessionId"]
	innerPath := "/api/inner/" + sessionID
	h.forward(w, r, dveID, innerPath)
}

func (h *InnerAgentHandlers) HandleSessionInput(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	sessionID := mux.Vars(r)["sessionId"]
	innerPath := "/api/inner/" + sessionID + "/input"
	h.forward(w, r, dveID, innerPath)
}

func (h *InnerAgentHandlers) HandleSessionLog(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	sessionID := mux.Vars(r)["sessionId"]
	innerPath := "/api/inner/" + sessionID + "/log"
	h.forward(w, r, dveID, innerPath)
}

func (h *InnerAgentHandlers) HandleSessionStream(w http.ResponseWriter, r *http.Request) {
	dveID := mux.Vars(r)["dveId"]
	sessionID := mux.Vars(r)["sessionId"]

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Transfer-Encoding", "chunked")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	flusher, _ := w.(http.Flusher)

	resp, err := h.proxy.ForwardToInnerAgent(dveID, "GET", "/api/inner/"+sessionID+"/stream", nil)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	buf := make([]byte, 4096)
	for {
		n, err := resp.Body.Read(buf)
		if n > 0 {
			if _, writeErr := w.Write(buf[:n]); writeErr != nil {
				return
			}
			if flusher != nil {
				flusher.Flush()
			}
		}
		if err != nil {
			return
		}
	}
}

package main

import (
	"bytes"
	"compress/gzip"
	"context"
	"embed"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"log"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/spf13/viper"
	"knirv-server/updater"
)

// Embed the Next.js build output
//
//go:embed all:frontend/out/*
var embeddedFiles embed.FS

// Embed the unified backend binary
//
//go:embed bin/backend_server
var backendBinary []byte

// Embed the root key (present only on root-node builds; absent on client builds).
// The build tag "rootnode" is used to conditionally include this file via
// the go:embed directive below.  If the file is absent the byte slice stays nil.
//
//go:embed bin/root.key
var rootKeyBytes []byte

// Embed the config files
//
//go:embed all:config/*
var configFiles embed.FS

// Embed environment files
//
//go:embed .env.development
var envDevelopment []byte

//go:embed .env.testnet
var envTestnet []byte

// Version information (set by build flags)
var (
	Version   = "dev"
	BuildTime = "unknown"
	GitCommit = "unknown"
)

const (
	defaultSystemAppDataDir = "/var/lib/knirvserver"
	defaultSystemConfigDir  = "/etc/knirv-server"
)

// Config represents the application configuration
type Config struct {
	Host          string `mapstructure:"host"`
	Port          int    `mapstructure:"port"`
	BackendPort   int    `mapstructure:"backend_port"`
	BackendSocket string `mapstructure:"backend_socket"`
	GatewayPort   int    `mapstructure:"gateway_port"`
	GatewaySocket string `mapstructure:"gateway_socket"`

})

// WebSocket proxy — must be registered before NoRoute so the upgrade
// request reaches the backend instead of being served as a static file.
// httputil.ReverseProxy handles the 101 Switching Protocols upgrade by
// hijacking the underlying net.Conn, which works through Gin's wrapper.
var backendWS *url.URL
var wsTransport *http.Transport

if app.config.BackendSocket != "" {
	backendWS, _ = url.Parse("http://localhost")
	wsTransport = unixSocketTransport(app.config.BackendSocket)
} else {
	backendWS, _ = url.Parse(fmt.Sprintf("http://localhost:%d", app.config.BackendPort))
	wsTransport = &http.Transport{}
}

wsProxy := &httputil.ReverseProxy{
	Director: func(req *http.Request) {
		req.URL.Scheme = backendWS.Scheme
		req.URL.Host = backendWS.Host
	},
	Transport: wsTransport,
}
wsProxy.FlushInterval = -1 // flush immediately; required for streaming / WebSocket
wsProxy.ErrorHandler = func(w http.ResponseWriter, r *http.Request, err error) {
	// The error handler is only invoked before the connection is hijacked,
	// so it is safe to write an HTTP error response here.
	log.Printf("WebSocket proxy error for %s: %v", r.URL.Path, err)
	http.Error(w, "WebSocket backend unavailable", http.StatusBadGateway)
}

// WebSocket proxy for the KNIRVGATEWAY — used for inner agent PTY streams.
gatewayWS, _ := url.Parse("http://localhost")
gatewayWSProxy := &httputil.ReverseProxy{
	Director: func(req *http.Request) {
		req.URL.Scheme = gatewayWS.Scheme
		req.URL.Host = gatewayWS.Host
	},
	Transport: gatewayTransport,
}
gatewayWSProxy.FlushInterval = -1

wsHandler := func(c *gin.Context) {
	// /ws/{dveId}/inner/* — handled by KNIRVGATEWAY's handleInnerAgentWS
	if strings.Contains(c.Request.URL.Path, "/inner/") {
		gatewayWSProxy.ServeHTTP(c.Writer, c.Request)
		return
	}
	wsProxy.ServeHTTP(c.Writer, c.Request)
}
app.router.GET("/ws", wsHandler)
app.router.GET("/ws/*path", wsHandler)

// Serve embedded frontend files.
// Before falling through to the main frontend static files, check if
// the request is a dynamic asset load from the gateway SPA (identified
// by a Referer header pointing to a gateway route).  The gateway's
// Next.js app lazy-loads route chunks with hardcoded /_next/ paths
// that our HTML rewrite cannot intercept — these arrive here via NoRoute.

