10		"sync"
11		"time"
12	
13		"github.com/gorilla/mux"
14		"github.com/gorilla/websocket"
15	)
16	
17	type InnerAgentManagerInterface interface {
18		InnerAgentClient(dveID string) (*http.Client, string, error)
19	}
20	
21	type DVEInnerAgentWSHandler struct {
22		agentManager InnerAgentManagerInterface
23		mu           sync.RWMutex
24		active       map[string]*innerWSConn
25	}
26	
27	type innerWSConn struct {
28		dveID      string
29		conn       *websocket.Conn
30		send       chan []byte
31		socketPath string
32		lastSeen   time.Time
33		mu         sync.Mutex
34	}
35	
36	type innerWSMessage struct {
37		Type    string `json:"type"`
38		Session string `json:"session,omitempty"`
39		Data    string `json:"data,omitempty"`
40	}
41	
42	type innerWSResponse struct {
43		Type string `json:"type"`
44		Data string `json:"data,omitempty"`
45	}
46	
47	func NewDVEInnerAgentWSHandler(mgr InnerAgentManagerInterface) *DVEInnerAgentWSHandler {
48		return &DVEInnerAgentWSHandler{
49			agentManager: mgr,
50			active:       make(map[string]*innerWSConn),
51		}
52	}
53	
54	func (h *DVEInnerAgentWSHandler) HandleWebSocket(w http.ResponseWriter, r *http.Request) {
55		vars := mux.Vars(r)
56		dveID := vars["dveId"]
57		if dveID == "" {
58			http.Error(w, "dveId required", http.StatusBadRequest)
59			return
60		}
61	
62		sessionID := vars["sessionId"]
63	
64		if h.agentManager == nil {
65			http.Error(w, "agent manager not available", http.StatusServiceUnavailable)
66			return
67		}
68	
69		_, socketPath, err := h.agentManager.InnerAgentClient(dveID)
70		if err != nil {
71			log.Printf("[DVE Inner Agent WS] No agent for DVE %s: %v", dveID, err)
72			http.Error(w, "no agent for DVE: "+err.Error(), http.StatusNotFound)
73			return
74		}
75	
76		conn, err := upgrader.Upgrade(w, r, nil)
77		if err != nil {
78			log.Printf("[DVE Inner Agent WS] Upgrade error DVE=%s: %v", dveID, err)
79			return
80		}
81	
82		wsConn := &innerWSConn{
83			dveID:      dveID,
84			conn:       conn,
85			send:       make(chan []byte, 256),
86			socketPath: socketPath,
87			lastSeen:   time.Now(),
88		}
89	
90		h.mu.Lock()
91		if existing, ok := h.active[dveID]; ok {
92			existing.conn.Close()
93		}
94		h.active[dveID] = wsConn
95		h.mu.Unlock()
96	
97		log.Printf("[DVE Inner Agent WS] Connected: DVE=%s socket=%s session=%s", dveID, socketPath, sessionID)
98	
99		if sessionID != "" {
100			go h.streamSession(wsConn, sessionID)
101		}
102		go h.writePump(wsConn)
103		go h.readPump(wsConn)
104	}
105	
106	func (h *DVEInnerAgentWSHandler) streamSession(conn *innerWSConn, sessionID string) {
107		unixDialer := net.Dialer{Timeout: 5 * time.Second}
108		unixConn, err := unixDialer.Dial("unix", conn.socketPath)
109		if err != nil {
110			conn.send <- mustMarshal(innerWSResponse{Type: "error", Data: "cannot connect to agent: " + err.Error()})
111			return
112		}
113		defer unixConn.Close()
114	
115		httpReq := "GET /api/inner/" + sessionID + "/stream HTTP/1.1\r\nHost: unix\r\n\r\n"
116		if _, err := unixConn.Write([]byte(httpReq)); err != nil {
117			conn.send <- mustMarshal(innerWSResponse{Type: "error", Data: "stream request failed: " + err.Error()})
118			return
119		}
120	
121		buf := make([]byte, 4096)
122		for {
123			n, err := unixConn.Read(buf)
124			if n > 0 {
125				// Skip HTTP headers on first read
126				data := buf[:n]
127				if len(data) > 0 {
128					conn.send <- mustMarshal(innerWSResponse{Type: "data", Data: string(data)})
129				}
130			}
131			if err != nil {
132				if err != io.EOF {
133					log.Printf("[DVE Inner Agent WS] Stream read error DVE=%s: %v", conn.dveID, err)
134				}
135				conn.send <- mustMarshal(innerWSResponse{Type: "stream_end", Data: ""})
136				return
137			}
138		}
139	}
140	
141	func (h *DVEInnerAgentWSHandler) readPump(conn *innerWSConn) {
142		defer func() {
143			h.mu.Lock()
144			delete(h.active, conn.dveID)
145			h.mu.Unlock()
146			conn.conn.Close()
147		}()
148	
149		conn.conn.SetReadLimit(65536)
150		conn.conn.SetReadDeadline(time.Now().Add(5 * time.Minute))
151		conn.conn.SetPongHandler(func(string) error {
152			conn.mu.Lock()
153			conn.lastSeen = time.Now()
154			conn.mu.Unlock()
155			conn.conn.SetReadDeadline(time.Now().Add(5 * time.Minute))
156			return nil
157		})
158	
159		for {
160			_, message, err := conn.conn.ReadMessage()
161			if err != nil {
162				if websocket.IsUnexpectedCloseError(err, websocket.CloseGoingAway, websocket.CloseNormalClosure) {
163					log.Printf("[DVE Inner Agent WS] Read error DVE=%s: %v", conn.dveID, err)
164				}
165				break
166			}
167	
168			var msg innerWSMessage
169			if err := json.Unmarshal(message, &msg); err != nil {
170				log.Printf("[DVE Inner Agent WS] Invalid message from DVE=%s: %v", conn.dveID, err)
171				continue
172			}
173	
174			switch msg.Type {
175			case "input":
176				if msg.Session == "" {
177					conn.send <- mustMarshal(innerWSResponse{Type: "error", Data: "session required"})
