44		s.mu.Lock()
45		defer s.mu.Unlock()
46		for i, sub := range s.subscribers {
47			if sub == ch {
48				s.subscribers = append(s.subscribers[:i], s.subscribers[i+1:]...)
49				return
50			}
51		}
52	}
53	
54	func (s *InnerAgentSession) broadcast(chunk []byte) {
55		s.supervisorLog.Write(chunk)
56		s.mu.RLock()
57		defer s.mu.RUnlock()
58		for _, ch := range s.subscribers {
59			select {
60			case ch <- append([]byte(nil), chunk...):
61			default:
62			}
63		}
64	}
65	
66	func (s *InnerAgentSession) PumpOutput() {
67		buf := make([]byte, 4096)
68		for {
69			n, err := s.PTY.Read(buf)
70			if n > 0 {
71				s.broadcast(buf[:n])
72			}
73			if err != nil {
74				break
75			}
76		}
77		s.mu.Lock()
78		s.Status = StatusExited
79		for _, ch := range s.subscribers {
80			close(ch)
81		}
82		s.subscribers = nil
83		s.mu.Unlock()
84		close(s.done)
85	}
