1	package knirvagent
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"net"
9		"net/http"
10		"os"
11		"os/exec"
12		"path/filepath"
13		"strings"
14		"sync"
15		"syscall"
16		"time"
17	
18		"go.uber.org/zap"
19	)
20	
21	// ──────────────────────────────────────────────
22	// Utility helpers (preserved from original)
23	// ──────────────────────────────────────────────
24	
25	// killStaleAgent sends SIGTERM (then SIGKILL after 2 s) to any running
26	// processes whose executable matches the given binary name.
27	func killStaleAgent(binaryPath string) {
28		if binaryPath == "" {
29			return
30		}
31		binaryName := filepath.Base(binaryPath)
32		if cmd := exec.Command("pkill", "-TERM", "-x", binaryName); cmd.Run() == nil {
33			time.Sleep(1 * time.Second)
34		}
35		exec.Command("pkill", "-KILL", "-x", binaryName).Run() //nolint:errcheck
36	}
37	
38	// waitForPortFree blocks until the given TCP port is no longer occupied or
39	// the deadline is reached. Returns true if the port is free.
40	func waitForPortFree(port int, deadline time.Duration) bool {
41		end := time.Now().Add(deadline)
42		for time.Now().Before(end) {
43			ln, err := net.Listen("tcp", fmt.Sprintf(":%d", port))
44			if err == nil {
45				ln.Close()
46				return true
47			}
48			time.Sleep(200 * time.Millisecond)
49		}
50		return false
51	}
52	
53	func getAgentAppDataDir() string {
54		if explicit := strings.TrimSpace(os.Getenv("KNIRV_APP_DATA_DIR")); explicit != "" {
55			return explicit
56		}
57		if err := os.MkdirAll("/var/lib/knirvserver", 0755); err == nil {
58			return "/var/lib/knirvserver"
59		}
60		if home, err := os.UserHomeDir(); err == nil {
61			return filepath.Join(home, ".local", "share", "knirvserver")
62		}
63		return "data"
64	}
65	
66	// resolveBinaryPath returns the first path where the knirvagent binary exists.
67	func resolveBinaryPath(configured string) (string, error) {
68		var candidates []string
69	
70		if envPath := os.Getenv("KNIRV_AGENT_BINARY_PATH"); envPath != "" {
71			candidates = append(candidates, envPath)
72		}
73	
74		if extractedPath, err := ExtractEmbeddedBinary(""); err == nil {
75			candidates = append(candidates, extractedPath)
76		}
77	
78		if exe, err := os.Executable(); err == nil {
79			exeDir := filepath.Dir(exe)
80			candidates = append(candidates,
81				filepath.Join(exeDir, "knirvagent"),
82				filepath.Join(exeDir, "bin", "knirvagent"),
83			)
84		}
85	
86		embeddedDir := filepath.Join(getAgentAppDataDir(), "bin")
87		candidates = append(candidates,
88			filepath.Join(embeddedDir, "knirvagent"),
89			filepath.Join(embeddedDir, "..", "bin", "knirvagent"),
90		)
91	
92		candidates = append(candidates, configured)
93	
94		dir, _ := os.Getwd()
95		candidates = append(candidates,
96			filepath.Join(dir, "bin", "knirvagent"),
97			filepath.Join(dir, "..", "bin", "knirvagent"),
98			filepath.Join(filepath.Dir(configured), "bin", "knirvagent"),
99		)
100	
101		for _, p := range candidates {
102			if _, err := os.Stat(p); err == nil {
103				return p, nil
104			}
105		}
106	
107		return "", fmt.Errorf("binary not found in any candidate location")
108	}
