110	// waitForSocket blocks until the given Unix socket file exists or the
111	// deadline is reached. Returns true when the socket is ready.
112	func waitForSocket(socketPath string, deadline time.Duration) bool {
113		end := time.Now().Add(deadline)
114		for time.Now().Before(end) {
115			if _, err := os.Stat(socketPath); err == nil {
116				// Socket file exists — verify it's actually listening
117				conn, err := net.DialTimeout("unix", socketPath, 100*time.Millisecond)
118				if err == nil {
119					conn.Close()
120					return true
121				}
122			}
123			time.Sleep(100 * time.Millisecond)
124		}
125		return false
126	}
127	
128	// waitForTCPPort blocks until the given TCP port is accepting connections or
129	// the deadline is reached. Returns true when the port is ready.
130	func waitForTCPPort(port int, deadline time.Duration) bool {
131		end := time.Now().Add(deadline)
132		addr := fmt.Sprintf("127.0.0.1:%d", port)
133		for time.Now().Before(end) {
134			conn, err := net.DialTimeout("tcp", addr, 100*time.Millisecond)
135			if err == nil {
136				conn.Close()
137				return true
138			}
139			time.Sleep(200 * time.Millisecond)
140		}
141		return false
142	}
