534	// GetSocketPath returns the Unix socket path for a given DVE's agent.
535	// If the agent was not started by this process (e.g. after a server restart),
536	// it falls back to checking whether the expected socket file exists on disk.
537	func (am *AgentManager) GetSocketPath(dveID string) (string, error) {
538		if ap, err := am.GetAgent(dveID); err == nil {
539			return ap.SocketPath, nil
540		}
541	
542		// Fallback: the socket might belong to an agent started before this server
543		// session (e.g. KNIRVSERVER was restarted while the DVE kept running).
544		if am.socketDir == "" {
545			return "", fmt.Errorf("no agent running for DVE %s and socketDir is not configured", dveID)
546		}
547		socketPath := filepath.Join(am.socketDir, fmt.Sprintf("agent-%s.sock", dveID))
548		if _, err := os.Stat(socketPath); err != nil {
549			return "", fmt.Errorf("no agent running for DVE %s (socket %s not found)", dveID, socketPath)
550		}
551		// Re-register as an AgentProcess so future lookups use the fast path.
552		// Mark it healthy since the socket file is present and connectable.
553		ap := &AgentProcess{
554			DVEID:      dveID,
555			SocketPath: socketPath,
556			StartedAt:  time.Now(),
557		}
558		ap.setHealthy(true)
559		am.mu.Lock()
560		am.agents[dveID] = ap
561		am.mu.Unlock()
562		return socketPath, nil
563	}
